    #include <iostream>
#include <vector>
#include <queue>
using namespace std;

// Returns total weight of the Minimum Spanning Tree
int spanningTree(int V, vector<vector<int>> adj[]) {

    // Min-heap storing {weight, vertex}
    priority_queue<pair<int,int>, vector<pair<int,int>>,
                                greater<pair<int,int>>> pq;

    // Marks vertices already taken in MST
    vector<bool> visited(V, false);

    int res = 0;

    // Start from node 0
    pq.push({0, 0});

    while(!pq.empty()) {

        auto p = pq.top();
        pq.pop();

        int wt = p.first;
        int u = p.second;

        if(visited[u])
            continue;

        res += wt;
        visited[u] = true;

        // Push adjacent edges
        for(auto &v : adj[u]) {

            if(!visited[v[0]]) {
                pq.push({v[1], v[0]});
            }
        }
    }

    return res;
}

int main() {

    int V = 3;
    vector<vector<int>> adj[V];

    adj[0].push_back({1, 5});
    adj[1].push_back({0, 5});

    adj[1].push_back({2, 3});
    adj[2].push_back({1, 3});

    adj[0].push_back({2, 1});
    adj[2].push_back({0, 1});

    cout << spanningTree(V, adj) << endl;

    return 0;
}


