            res += wt;
            visited[u] = true;

            // Push adjacent edges
            for(int[] v : adj.get(u)) {
                if(!visited[v[0]]) {
                    pq.add(new int[]{v[1], v[0]});
                }
            }
        }

        return res;
    }

